import { GET_WISHLIST_BY_ID_QUERY } from '@/wishlist/api/getWishlistById/graphql/getWishlistById.graphql';
import { Wishlist } from '@/wishlist/data/models';
import { transformWishlist } from '@/wishlist/data/transforms';
import { state } from '@/wishlist/lib/state';
import { fetchGraphQl, getPersistedWishlistData } from '@/wishlist/api';
import { handleFetchError } from '@/wishlist/lib/fetch-error';
import { events } from '@adobe-commerce/event-bus';
import {
  DEFAULT_PAGE_SIZE,
  DEFAULT_CURRENT_PAGE,
} from '@/wishlist/api/constants';

export const getWishlistById = async (
  wishlistId: string,
  pageSize: number = DEFAULT_PAGE_SIZE,
  currentPage: number = DEFAULT_CURRENT_PAGE,
  options: { scope?: string } = {}
): Promise<void | Wishlist | null> => {
  // `scope` routes the `wishlist/data` broadcast to a specific channel so a
  // second container (e.g. Save for Later) can render its own list without
  // colliding with the active/default list (which listens unscoped). The read
  // always broadcasts; callers that only need the data should read it directly.
  const { scope } = options;

  // Guests have no server-side lists. Read the requested list from local
  // storage using `wishlistId` as the guest list key; when it's the default
  // guest wishlist there is no key and this returns the base blob unchanged.
  if (!state.authenticated) {
    const guestData = getPersistedWishlistData(true, wishlistId || undefined);
    // A scoped read broadcasts so a scoped guest container (e.g. SFL) renders;
    // the default guest read stays silent, exactly as before.
    if (scope) {
      events.emit('wishlist/data', guestData as Wishlist, { scope });
    }
    return guestData;
  }

  if (!wishlistId) {
    throw Error('Wishlist ID is not set');
  }

  // @ts-ignore
  return fetchGraphQl(GET_WISHLIST_BY_ID_QUERY, {
    variables: {
      wishlistId,
      pageSize,
      currentPage,
    },
  }).then(({ errors, data }) => {
    if (errors) return handleFetchError(errors);

    if (!data?.customer?.wishlist_v2) {
      return null;
    }

    const payload = transformWishlist(data.customer.wishlist_v2);
    events.emit('wishlist/data', payload, { scope });
    return payload;
  });
};
