import { fetchGraphQl } from '@/wishlist/api';
import { state } from '@/wishlist/lib/state';
import { handleFetchError } from '@/wishlist/lib/fetch-error';
import { REMOVE_PRODUCTS_FROM_WISHLIST_MUTATION } from './graphql/removeProductsFromWishlistMutation';
import { Item, Wishlist } from '@/wishlist/data/models/wishlist';
import { events } from '@adobe-commerce/event-bus';
import {
  getPersistedWishlistData,
  setPersistedWishlistData,
  addToPersistedAllWishlistItems,
  removeFromPersistedAllWishlistItems,
} from '@/wishlist/lib/persisted-data';
import { isMatchingWishlistItem } from '@/wishlist/lib/wishlist-item-comparator';
import { getWishlistById } from '@/wishlist/api/getWishlistById';

export const removeProductsFromWishlist = async (
  items: Array<Item>,
  wishlistId?: string,
  options: { scope?: string } = {}
): Promise<Wishlist | null> => {
  const { scope } = options;
  // Targeted removal: authenticated caller removing from a specific list.
  // Server-only, non-emitting, and does not touch the active-list caches; the
  // caller is responsible for refreshing the list it rendered.
  if (state.authenticated && wishlistId) {
    const itemIds = items.map((item) => item.id);
    const { errors, data } = await fetchGraphQl(
      REMOVE_PRODUCTS_FROM_WISHLIST_MUTATION,
      {
        variables: { wishlistId, wishlistItemsIds: itemIds },
      }
    );

    const _errors = [
      ...(data?.removeProductsFromWishlist?.user_errors ?? []),
      ...(errors ?? []),
    ];

    if (_errors.length > 0) {
      return handleFetchError(_errors);
    }

    return null;
  }

  // Targeted removal for guests: a passed wishlistId maps to a keyed local list
  // (e.g. Save for Later). Filter that list's stored blob, persist it, and
  // broadcast it on `scope` so the scoped consumer updates without re-reading;
  // return the updated list. The default list's all-items cache is untouched,
  // and the emit is scoped so it never overwrites the active list.
  if (!state.authenticated && wishlistId) {
    const targetWishlist = getPersistedWishlistData(
      true,
      wishlistId
    ) as Wishlist;

    const updatedTarget = {
      ...targetWishlist,
      items: targetWishlist.items?.filter((wishlistItem: any) => {
        return !items.some((item) =>
          isMatchingWishlistItem(wishlistItem, {
            sku: item.product.sku,
            optionUIDs: item.selectedOptions?.map((option: any) => option.uid),
          })
        );
      }),
    };

    updatedTarget.items_count = updatedTarget.items?.length;
    setPersistedWishlistData(updatedTarget as Wishlist, wishlistId);

    if (scope) {
      events.emit('wishlist/data', updatedTarget as Wishlist, { scope });
    }

    return updatedTarget as Wishlist;
  }

  const wishlist = getPersistedWishlistData();
  const updatedWishlist = {
    ...wishlist,
    items: wishlist.items?.filter((wishlistItem: any) => {
      return !items.some((item) =>
        isMatchingWishlistItem(wishlistItem, {
          sku: item.product.sku,
          optionUIDs: item.selectedOptions?.map((option: any) => option.uid),
        })
      );
    }),
  };

  if (state.authenticated) {
    if (!state.wishlistId) {
      throw Error('Wishlist ID is not set');
    }

    removeFromPersistedAllWishlistItems(items);

    const itemIds = items.map((item) => item.id);
    const { errors, data } = await fetchGraphQl(
      REMOVE_PRODUCTS_FROM_WISHLIST_MUTATION,
      {
        variables: { wishlistId: state.wishlistId, wishlistItemsIds: itemIds },
      }
    );

    const _errors = [
      ...(data?.removeProductsFromWishlist?.user_errors ?? []),
      ...(errors ?? []),
    ];

    if (_errors.length > 0) {
      addToPersistedAllWishlistItems(items);
      events.emit('wishlist/data', wishlist);
      return handleFetchError(_errors);
    }

    // Re-fetch the current page from the server so the pagination state remains
    // accurate. The locally-filtered data only contains the current page's items,
    // so emitting it directly can show an empty panel when items remain on other pages.
    await getWishlistById(state.wishlistId, state.pageSize, state.currentPage);
    return null;
  }

  removeFromPersistedAllWishlistItems(items);
  updatedWishlist.items_count = updatedWishlist.items?.length;
  events.emit('wishlist/data', updatedWishlist);

  return null;
};
