import { events } from '@adobe-commerce/event-bus';
import { fetchGraphQl } from '@/wishlist/api';
import { GET_WISHLIST_BY_ID_QUERY } from '@/wishlist/api/getWishlistById/graphql/getWishlistById.graphql';
import { transformWishlist } from '@/wishlist/data/transforms';
import { Wishlist, Item } from '@/wishlist/data/models/wishlist';
import {
  setPersistedAllWishlistItems,
  getAllItemsCacheVersion,
} from '@/wishlist/lib/persisted-data';

/**
 * Fetches ALL wishlist items across all pages and stores them in the
 * in-memory all-items store. Called non-blocking after initialization
 * so WishlistToggle can accurately determine heart icon state for
 * products on any page.
 *
 * Uses a generation check to abort if the store was reset or re-seeded
 * (e.g. logout, auth change, or mutation) while fetches were in flight.
 */
export async function populateAllWishlistItems(
  wishlistId: string,
  firstPageWishlist: Wishlist,
  pageSize: number
): Promise<void> {
  const totalPages = firstPageWishlist.page_info?.totalPages ?? 1;
  const firstPageItems = firstPageWishlist.items ?? [];

  if (totalPages <= 1) {
    return;
  }

  const startGeneration = getAllItemsCacheVersion();

  const remainingPages = Array.from(
    { length: totalPages - 1 },
    (_, i) => i + 2
  );

  const results = await Promise.all(
    remainingPages.map((page) =>
      fetchGraphQl(GET_WISHLIST_BY_ID_QUERY, {
        variables: { wishlistId, pageSize, currentPage: page },
      })
        .then(({ data }) => {
          if (!data?.customer?.wishlist_v2) return [];
          const wishlist = transformWishlist(data.customer.wishlist_v2);
          return wishlist?.items ?? [];
        })
        .catch(() => [] as Item[])
    )
  );

  if (getAllItemsCacheVersion() !== startGeneration) {
    return;
  }

  const allItems = [...firstPageItems, ...results.flat()];
  setPersistedAllWishlistItems(allItems);
  events.emit('wishlist/allItems', allItems);
}
