import { Wishlist, Item } from '@/wishlist/data/models';
import { addProductsToWishlist } from '@/wishlist/api';
import {
  getPersistedWishlistData,
  clearPersistedLocalStorage,
} from '@/wishlist/lib/persisted-data';
import { isMatchingWishlistItem } from '@/wishlist/lib/wishlist-item-comparator';

export const mergeWishlists = async (
  wishlist: Wishlist,
  listKey?: string
): Promise<Wishlist | null> => {
  if (!wishlist) {
    return null;
  }

  // `listKey` selects a specific guest list to
  // merge into `wishlist`. When omitted, the default guest wishlist is merged
  // into the active list, preserving the original behavior.
  const guestWishlist: {
    id?: string;
    items?: Item[];
  } = getPersistedWishlistData(true, listKey);
  const itemsToMerge: any[] = [];

  guestWishlist?.items?.forEach((item: any) => {
    const optionUIDs =
      item.selectedOptions?.map((option: any) => option.uid) || [];

    const exists = wishlist.items.some((wishlistItem: any) =>
      isMatchingWishlistItem(wishlistItem, {
        sku: item.product.sku,
        optionUIDs,
      })
    );

    if (!exists) {
      const mergeItem = {
        sku: item.product.sku,
        quantity: 1,
        optionsUIDs: optionUIDs,
        enteredOptions: item.enteredOptions || undefined,
      };

      itemsToMerge.push(mergeItem);
    }
  });

  if (itemsToMerge.length === 0) {
    // A keyed guest list is still cleared so it is not re-merged on a later
    // login; the default path is left untouched to preserve prior behavior.
    if (listKey) {
      clearPersistedLocalStorage(listKey);
    }
    return null;
  }

  // For a keyed list, add to that specific server list (targeted, non-emitting);
  // otherwise add to the active/default list as before.
  const result = listKey
    ? await addProductsToWishlist(itemsToMerge, wishlist.id)
    : await addProductsToWishlist(itemsToMerge);
  clearPersistedLocalStorage(listKey);
  return result;
};
