import { Wishlist, Item } from '@/wishlist/data/models';
import { state } from '@/wishlist/lib/state';
import { isMatchingWishlistItem } from '@/wishlist/lib/wishlist-item-comparator';

const WISHLIST_KEY_BASE = 'DROPIN__WISHLIST__WISHLIST__DATA';
const ALL_ITEMS_KEY_BASE = 'DROPIN__WISHLIST__ALL_ITEMS__DATA';

const getStorageKey = (base: string): string =>
  state.storeCode && state.storeCode !== 'default'
    ? `${base}__${state.storeCode}`
    : base;

const getStorage = (guest: boolean = false) =>
  state.authenticated && !guest ? sessionStorage : localStorage;

// A specific list is stored under its own key (`..._<listKey>`); the default
// guest wishlist uses the base key unchanged.
const getWishlistKey = (listKey?: string): string =>
  getStorageKey(
    listKey ? `${WISHLIST_KEY_BASE}__${listKey}` : WISHLIST_KEY_BASE
  );

// Per-list guest expiry: only a keyed list with a configured TTL expires; the
// default guest wishlist (no listKey) never expires.
const getGuestTtlMs = (listKey?: string): number => {
  if (!listKey) return 0;
  const days = state.guestWishlistTtl?.[listKey];
  return typeof days === 'number' && days > 0
    ? days * 24 * 60 * 60 * 1000
    : 0;
};

export function setPersistedWishlistData(
  data: Wishlist | null,
  listKey?: string
) {
  const $storage = getStorage();
  const key = getWishlistKey(listKey);
  if (data) {
    // Stamp the save time only for lists that have a configured TTL, so the
    // default guest wishlist blob stays byte-identical to before.
    const payload =
      getGuestTtlMs(listKey) > 0 ? { ...data, savedAt: Date.now() } : data;
    try {
      $storage.setItem(key, JSON.stringify(payload));
    } catch (error) {
      if (isQuotaExceededError(error)) {
        console.error('Storage quota exceeded:', error);
      } else {
        console.error('Error saving wishlist:', error);
      }
    }
  } else {
    $storage.removeItem(key);
  }
}

const isQuotaExceededError = (error: unknown) => {
  //https://mmazzarolo.com/blog/2022-06-25-local-storage-status/
  return error instanceof DOMException && error.name === 'QuotaExceededError';
};

export function getPersistedWishlistData(
  guest: boolean = false,
  listKey?: string
): Wishlist | {} {
  const $storage = getStorage(guest);
  const key = getWishlistKey(listKey);
  try {
    const raw = $storage.getItem(key);
    if (!raw) return { id: '', items: [] };

    const wishlist = JSON.parse(raw);

    // Expire only a keyed list with a configured TTL and a save timestamp;
    // legacy blobs without `savedAt` are treated as not expired.
    const ttlMs = getGuestTtlMs(listKey);
    if (ttlMs > 0 && wishlist.savedAt && Date.now() - wishlist.savedAt > ttlMs) {
      $storage.removeItem(key);
      return { id: '', items: [] };
    }

    return wishlist;
  } catch (error) {
    console.error('Error retrieving wishlist:', error);
    return { id: '', items: [] };
  }
}

export function clearPersistedLocalStorage(listKey?: string) {
  localStorage.removeItem(getWishlistKey(listKey));
}

export function getWishlistItemFromStorage(
  productSku: string,
  optionUIDs: string[] = []
) {
  const storage = getStorage();
  const key = getWishlistKey();
  const raw = storage.getItem(key);
  const wishlist = raw ? JSON.parse(raw) : { id: '', items: [] };

  return wishlist?.items?.find((item: any) =>
    isMatchingWishlistItem(item, {
      sku: productSku,
      optionUIDs,
    })
  );
}

// ---------------------------------------------------------------------------
// All-items storage: keeps every wishlist item across all pages so that
// WishlistToggle can determine heart-icon state regardless of pagination.
// Uses the same sessionStorage (auth) / localStorage (guest) pattern.
// ---------------------------------------------------------------------------

const getAllItemsKey = (): string => getStorageKey(ALL_ITEMS_KEY_BASE);

let allItemsGeneration = 0;

export function getAllItemsCacheVersion(): number {
  return allItemsGeneration;
}

function readAllItems(): Item[] {
  try {
    const raw = getStorage().getItem(getAllItemsKey());
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function writeAllItems(items: Item[]): void {
  try {
    getStorage().setItem(getAllItemsKey(), JSON.stringify(items));
  } catch (error) {
    if (isQuotaExceededError(error)) {
      console.error('Storage quota exceeded (all-items):', error);
    }
  }
}

export function setPersistedAllWishlistItems(items: Item[]): void {
  allItemsGeneration++;
  writeAllItems(items);
}

export function getPersistedAllWishlistItems(): Item[] {
  return readAllItems();
}

export function clearPersistedAllWishlistItems(): void {
  allItemsGeneration++;
  const key = getAllItemsKey();
  sessionStorage.removeItem(key);
  localStorage.removeItem(key);
}

export function addToPersistedAllWishlistItems(items: Item[]): void {
  allItemsGeneration++;
  writeAllItems([...readAllItems(), ...items]);
}

export function removeFromPersistedAllWishlistItems(items: Item[]): void {
  allItemsGeneration++;
  const current = readAllItems();
  writeAllItems(
    current.filter(
      (existing) =>
        !items.some((item) =>
          isMatchingWishlistItem(existing, {
            sku: item.product.sku,
            optionUIDs: item.selectedOptions?.map((o: any) => o.uid),
          })
        )
    )
  );
}

export function findInPersistedAllWishlistItems(
  sku: string,
  optionUIDs?: string[]
): Item | undefined {
  return readAllItems().find((item) =>
    isMatchingWishlistItem(item, { sku, optionUIDs })
  );
}
