import { fetchGraphQl } from '@/wishlist/api';
import { state } from '@/wishlist/lib/state';
import { handleFetchError } from '@/wishlist/lib/fetch-error';
import { CREATE_WISHLIST_MUTATION } from './graphql/createWishlistMutation';
import { Wishlist } from '@/wishlist/data/models/wishlist';
import { transformWishlist } from '@/wishlist/data/transforms';
import {
  DEFAULT_PAGE_SIZE,
  DEFAULT_CURRENT_PAGE,
} from '@/wishlist/api/constants';

export type WishlistVisibility = 'PUBLIC' | 'PRIVATE';

/**
 * Creates a new, additional wishlist for the logged-in customer.
 *
 * Creating a wishlist is a server-side, customer-scoped operation and
 * requires the store to have multiple wishlists enabled. Guests have a
 * single local list and cannot create additional lists, so the call is a
 * no-op for them. The default wishlist and guest behavior are unchanged.
 *
 * @param name The name of the wishlist to create.
 * @param visibility Whether the wishlist is PRIVATE (default) or PUBLIC.
 * @returns The created wishlist, or null.
 */
export const createWishlist = async (
  name: string,
  visibility: WishlistVisibility = 'PRIVATE'
): Promise<Wishlist | null> => {
  // Guests cannot create server-side wishlists.
  if (!state.authenticated) {
    return null;
  }

  if (!name?.trim()) {
    throw Error('Wishlist name is required');
  }

  const variables = {
    name,
    visibility,
    pageSize: state.pageSize ?? DEFAULT_PAGE_SIZE,
    currentPage: state.currentPage ?? DEFAULT_CURRENT_PAGE,
  };

  const { errors, data }: { errors: any; data: any } = await fetchGraphQl(
    CREATE_WISHLIST_MUTATION,
    { variables }
  );

  if (errors) {
    return handleFetchError(errors);
  }

  const wishlist = data?.createWishlist?.wishlist;

  if (!wishlist) {
    return null;
  }

  return transformWishlist(wishlist);
};
