import { WISHLIST_FRAGMENT } from '@/wishlist/api/fragments';

export const CREATE_WISHLIST_MUTATION = `
  mutation CREATE_WISHLIST_MUTATION(
    $name: String!,
    $visibility: WishlistVisibilityEnum!,
    $pageSize: Int = 9,
    $currentPage: Int = 1,
  ) {
    createWishlist(
      input: { name: $name, visibility: $visibility }
    ) {
      wishlist {
        ...WISHLIST_FRAGMENT
      }
    }
  }
${WISHLIST_FRAGMENT}
`;
