import { fetchGraphQl, getPersistedWishlistData } from '@/wishlist/api';
import { state } from '@/wishlist/lib/state';
import { handleFetchError } from '@/wishlist/lib/fetch-error';
import { ADD_PRODUCTS_TO_WISHLIST_MUTATION } from './graphql/addProductsToWishlistMutation';
import { Wishlist } from '@/wishlist/data/models/wishlist';
import { transformWishlist } from '@/wishlist/data/transforms';
import { events } from '@adobe-commerce/event-bus';
import { isMatchingWishlistItem } from '@/wishlist/lib/wishlist-item-comparator';
import {
  addToPersistedAllWishlistItems,
  removeFromPersistedAllWishlistItems,
  setPersistedWishlistData,
} from '@/wishlist/lib/persisted-data';
import { populateAllWishlistItems } from '@/wishlist/api/populateAllWishlistItems/populateAllWishlistItems';
import { DEFAULT_PAGE_SIZE } from '@/wishlist/api/constants';

export const addProductsToWishlist = async (
  items: [
    {
      sku: string;
      quantity: number;
      optionsUIDs?: string[]; // should be the options available for the product
      enteredOptions?: { uid: string; value: string }[]; // refer to both selected and entered options
    }
  ],
  wishlistId?: string,
  options: { scope?: string } = {}
): Promise<Wishlist | null> => {
  if (!items) return null;

  const { scope } = options;

  // Targeted add: when an authenticated caller passes a wishlistId, add
  // directly to that specific list. This skips the active/default list's
  // optimistic local update and the `wishlist/data` event (both represent
  // the active list) and returns the updated target wishlist. Guests are
  // unaffected and keep their single local list.
  if (state.authenticated && wishlistId) {
    const variables = {
      wishlistId,
      wishlistItems: items.map(
        ({ sku, quantity, optionsUIDs, enteredOptions }) => ({
          sku,
          quantity,
          selected_options: optionsUIDs,
          entered_options: enteredOptions,
        })
      ),
      pageSize: state.pageSize,
      currentPage: state.currentPage ?? 1,
    };

    const { errors, data }: { errors: any; data: any } = await fetchGraphQl(
      ADD_PRODUCTS_TO_WISHLIST_MUTATION,
      { variables }
    );

    const _errors = [
      ...(data?.addProductsToWishlist?.user_errors ?? []),
      ...(errors ?? []),
    ];

    if (_errors.length > 0) {
      return handleFetchError(_errors);
    }

    return transformWishlist(
      data.addProductsToWishlist.wishlist,
      items[0]?.enteredOptions ?? []
    );
  }

  // Targeted add for guests: a passed wishlistId maps to a keyed local list.
  // Persist under that key with its own TTL, broadcast the updated list on
  // `scope` (so the scoped consumer updates without re-reading), and return it.
  // The emit is scoped so it never overwrites the default list, and the
  // all-items heart-icon cache (which tracks the default list only) is untouched.
  if (!state.authenticated && wishlistId) {
    const targetWishlist = getPersistedWishlistData(
      true,
      wishlistId
    ) as Wishlist;

    const updatedTarget = {
      id: targetWishlist?.id ?? '',
      updated_at: '',
      sharing_code: '',
      items_count: 0,
      items: targetWishlist?.items ?? [],
    };

    for (const item of items) {
      const skuExists = updatedTarget.items?.some((wishlistItem: any) =>
        isMatchingWishlistItem(wishlistItem, {
          sku: item.sku,
          optionUIDs: item.optionsUIDs,
        })
      );

      if (skuExists) {
        continue;
      }

      const selectedOptions: { uid: string }[] = item.optionsUIDs
        ? item.optionsUIDs?.map((option: any) => ({ uid: option }))
        : [];

      updatedTarget.items = [
        ...updatedTarget.items,
        {
          id: crypto.randomUUID(),
          quantity: item.quantity,
          selectedOptions,
          enteredOptions: item.enteredOptions ?? [],
          product: { sku: item.sku },
        },
      ];
    }

    updatedTarget.items_count = updatedTarget.items?.length;
    setPersistedWishlistData(updatedTarget as Wishlist, wishlistId);

    // Broadcast on `scope` so the scoped consumer updates without re-reading;
    // scoped so it never overwrites the active list's cache.
    if (scope) {
      events.emit('wishlist/data', updatedTarget as Wishlist, { scope });
    }

    return updatedTarget as Wishlist;
  }

  const wishlist = getPersistedWishlistData() as Wishlist;
  const updatedWishlist = {
    id: wishlist?.id ?? '',
    updated_at: '',
    sharing_code: '',
    items_count: 0,
    items: wishlist?.items ?? [],
  };

  for (const item of items) {
    const skuExists = updatedWishlist.items?.some((wishlistItem: any) =>
      isMatchingWishlistItem(wishlistItem, {
        sku: item.sku,
        optionUIDs: item.optionsUIDs,
      })
    );

    if (skuExists) {
      continue;
    }

    const selectedOptions: { uid: string }[] = item.optionsUIDs
      ? item.optionsUIDs?.map((option: any) => ({
          uid: option,
        }))
      : [];

    updatedWishlist.items = [
      ...updatedWishlist.items,
      {
        id: crypto.randomUUID(),
        quantity: item.quantity,
        selectedOptions,
        enteredOptions: item.enteredOptions ?? [],
        product: { sku: item.sku },
      },
    ];
  }

  const newItems = updatedWishlist.items.slice((wishlist?.items ?? []).length);

  updatedWishlist.items_count = updatedWishlist.items?.length;
  addToPersistedAllWishlistItems(newItems);
  events.emit('wishlist/data', updatedWishlist);

  if (state.authenticated) {
    if (!state.wishlistId) {
      removeFromPersistedAllWishlistItems(newItems);
      events.emit('wishlist/data', wishlist);
      throw Error('Wishlist ID is not set');
    }

    const variables = {
      wishlistId: state.wishlistId,
      wishlistItems: items.map(
        ({ sku, quantity, optionsUIDs, enteredOptions }) => ({
          sku,
          quantity,
          selected_options: optionsUIDs,
          entered_options: enteredOptions,
        })
      ),
      pageSize: state.pageSize,
      currentPage: state.currentPage ?? 1,
    };

    const { errors, data }: { errors: any; data: any } = await fetchGraphQl(
      ADD_PRODUCTS_TO_WISHLIST_MUTATION,
      { variables }
    );

    const _errors = [
      ...(data?.addProductsToWishlist?.user_errors ?? []),
      ...(errors ?? []),
    ];

    if (_errors.length > 0) {
      removeFromPersistedAllWishlistItems(newItems);
      events.emit('wishlist/data', wishlist);
      return handleFetchError(_errors);
    }

    const updatedWishlist = transformWishlist(
      data.addProductsToWishlist.wishlist,
      items[0]?.enteredOptions ?? []
    );

    const serverItems = updatedWishlist?.items ?? [];

    const optimisticItemsOnCurrentPage = newItems.filter(
      (optimisticItem: any) =>
        serverItems.some((serverItem: any) =>
          isMatchingWishlistItem(serverItem, {
            sku: optimisticItem.product.sku,
            optionUIDs: optimisticItem.selectedOptions?.map((o: any) => o.uid),
          })
        )
    );

    if (optimisticItemsOnCurrentPage.length > 0) {
      removeFromPersistedAllWishlistItems(optimisticItemsOnCurrentPage);
      addToPersistedAllWishlistItems(
        serverItems.filter((serverItem: any) =>
          optimisticItemsOnCurrentPage.some((optimisticItem: any) =>
            isMatchingWishlistItem(serverItem, {
              sku: optimisticItem.product.sku,
              optionUIDs: optimisticItem.selectedOptions?.map(
                (o: any) => o.uid
              ),
            })
          )
        )
      );
    }

    events.emit('wishlist/data', updatedWishlist);

    if (
      optimisticItemsOnCurrentPage.length < newItems.length &&
      updatedWishlist
    ) {
      populateAllWishlistItems(
        state.wishlistId!,
        updatedWishlist,
        state.pageSize ?? DEFAULT_PAGE_SIZE
      ).catch(console.error);
    }
  }

  return null;
};
